import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Build, Deploy & Debug","description":"","frontmatter":{"title":"Build, Deploy & Debug","order":5},"headers":[],"relativePath":"learn/mod/build-debug.md","filePath":"learn/mod/build-debug.md","lastUpdated":1786957039000}'),s={name:"learn/mod/build-debug.md"};function n(l,e,r,d,h,p){return t(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="build-deploy-debug" tabindex="-1">Build, Deploy &amp; Debug <a class="header-anchor" href="#build-deploy-debug" aria-label="Permalink to &quot;Build, Deploy &amp; Debug&quot;">​</a></h1><p>You&#39;ve written the code — now how do you get it running in the game?</p><h2 id="compiling" tabindex="-1">Compiling <a class="header-anchor" href="#compiling" aria-label="Permalink to &quot;Compiling&quot;">​</a></h2><p>Use Visual Studio / Rider or the command line:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Debug</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The template project references <strong>DLLs from the game directory</strong>, so before building make sure:</p><ul><li>The game has been set up with UMM (injected)</li><li>The assembly paths in <code>.csproj</code> exist (usually <code>$(ADOFAI_PATH)</code> or a relative path)</li></ul><h2 id="deploying-put-the-output-in-mods" tabindex="-1">Deploying: Put the Output in Mods <a class="header-anchor" href="#deploying-put-the-output-in-mods" aria-label="Permalink to &quot;Deploying: Put the Output in Mods&quot;">​</a></h2><p>The template usually has &quot;auto-copy after build&quot; configured:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MyFirstMod.dll  →  ADOFAI/Mods/MyFirstMod/</span></span>
<span class="line"><span>Info.json       →  ADOFAI/Mods/MyFirstMod/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>If the template doesn&#39;t auto-deploy, copy manually. <strong>When publishing, you also need to put these two files together.</strong></p><h2 id="verifying-in-game" tabindex="-1">Verifying in Game <a class="header-anchor" href="#verifying-in-game" aria-label="Permalink to &quot;Verifying in Game&quot;">​</a></h2><ol><li>Launch the game and open the UMM interface (default <code>Ctrl+F10</code>)</li><li>Find MyFirstMod in the Mod list and check the enable box</li><li>Watch the log for <code>Mod loaded</code> output</li><li>If your Mod isn&#39;t in the list, check: <ul><li>Does <code>Info.json</code>&#39;s <code>AssemblyName</code> match the actual DLL filename</li><li>Is <code>EntryMethod</code> in the format <code>Namespace.Class.Load</code></li><li>Was the compiled output actually copied to <code>Mods/</code></li></ul></li></ol><h2 id="debugging-tips" tabindex="-1">Debugging Tips <a class="header-anchor" href="#debugging-tips" aria-label="Permalink to &quot;Debugging Tips&quot;">​</a></h2><h3 id="_1-use-logs-to-locate-problems" tabindex="-1">1. Use Logs to Locate Problems <a class="header-anchor" href="#_1-use-logs-to-locate-problems" aria-label="Permalink to &quot;1. Use Logs to Locate Problems&quot;">​</a></h3><div class="language-csharp vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">modEntry.Logger.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">$&quot;Current value: {</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">value</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Output to UMM interface</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_2-hot-reload-after-changes" tabindex="-1">2. Hot Reload After Changes <a class="header-anchor" href="#_2-hot-reload-after-changes" aria-label="Permalink to &quot;2. Hot Reload After Changes&quot;">​</a></h3><p>UMM supports <strong>disabling then re-enabling</strong> a Mod in-game: uncheck then recheck it in the UMM interface. This applies new code without restarting the game (provided you&#39;ve recompiled and overwritten the DLL).</p><h3 id="_3-check-player-log-on-crash" tabindex="-1">3. Check Player.log on Crash <a class="header-anchor" href="#_3-check-player-log-on-crash" aria-label="Permalink to &quot;3. Check Player.log on Crash&quot;">​</a></h3><p>Exceptions thrown by your Mod are written to the game log (see <a href="./umm">Getting to Know UMM</a> for log location). When you see <code>NullReferenceException</code>, first check:</p><ul><li>Did you access <code>Settings</code> before <code>OnToggle</code></li><li>Does your Harmony patch signature match the target method</li></ul><h3 id="_4-attach-a-debugger-optional" tabindex="-1">4. Attach a Debugger (Optional) <a class="header-anchor" href="#_4-attach-a-debugger-optional" aria-label="Permalink to &quot;4. Attach a Debugger (Optional)&quot;">​</a></h3><p>In your IDE, use &quot;Attach to Process&quot; and select <code>A Dance of Fire and Ice.exe</code> to set breakpoints directly in C# code. Note: you need to compile in <strong>Debug configuration</strong>, and the game must be running first.</p><h2 id="what-you-learned" tabindex="-1">What You Learned <a class="header-anchor" href="#what-you-learned" aria-label="Permalink to &quot;What You Learned&quot;">​</a></h2><ul><li>How to compile and deploy a Mod to the game directory</li><li>How to enable, verify, and hot-reload a Mod in-game</li><li>How to troubleshoot using logs and <code>Player.log</code></li></ul><h2 id="next-step" tabindex="-1">Next Step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next Step&quot;">​</a></h2><p>Learn to modify game behavior with Harmony → <a href="./harmony">Harmony Introduction</a></p>`,27)])])}const g=a(s,[["render",n]]);export{u as __pageData,g as default};
